/**
 * Course builder preview for Adaptive Learning streams and quiz forks.
 *
 * In-memory only. Nothing here is saved with the course.
 */
( function( $ ) {

	var streams = [];
	var assignments = {};
	var filter = '';
	var quizForks = {};
	var activeLesson = null;
	var started = false;
	var applying = false;

	function slugify( name ) {
		return String( name || '' )
			.toLowerCase()
			.replace( /[^a-z0-9]+/g, '-' )
			.replace( /^-|-$/g, '' );
	}

	function uniqueId( name ) {
		var base = slugify( name ) || 'stream';
		var id = base;
		var i = 2;
		var used = streams.map( function( stream ) {
			return stream.id;
		} );

		while ( used.indexOf( id ) !== -1 ) {
			id = base + '-' + i;
			i++;
		}

		return id;
	}

	function course() {
		return window.llms_builder && window.llms_builder.CourseModel;
	}

	function eachLesson( callback ) {
		var model = course();

		if ( ! model || ! model.get( 'sections' ) ) {
			return;
		}

		model.get( 'sections' ).each( function( section ) {
			if ( ! section.get( 'lessons' ) ) {
				return;
			}

			section.get( 'lessons' ).each( function( lesson ) {
				callback( lesson, section );
			} );
		} );
	}

	function lessonTags( lessonId ) {
		return assignments[ String( lessonId ) ] || [];
	}

	function lessonInFilter( lessonId ) {
		if ( ! filter ) {
			return true;
		}

		var tags = lessonTags( lessonId );

		if ( ! tags.length ) {
			return true;
		}

		return tags.indexOf( filter ) !== -1;
	}

	function streamName( id ) {
		var match = streams.filter( function( stream ) {
			return stream.id === id;
		} )[ 0 ];

		return match ? match.name : id;
	}

	function escapeHtml( value ) {
		return $( '<div>' ).text( value == null ? '' : String( value ) ).html();
	}

	function ensureBar() {
		if ( $( '#llms-adaptive-bar' ).length || ! $( '#llms-outline' ).length ) {
			return;
		}

		$( '#llms-outline' ).prepend(
			'<div id="llms-adaptive-bar">' +
				'<div class="llms-adaptive-define">' +
					'<span class="llms-label"><span class="llms-label-text">Streams</span></span>' +
					'<ul id="llms-adaptive-stream-list"></ul>' +
					'<input id="llms-adaptive-stream-name" class="llms-input" type="text" placeholder="Stream name">' +
					'<button type="button" class="llms-button-secondary small" id="llms-adaptive-stream-add">Add stream</button>' +
				'</div>' +
				'<label class="llms-adaptive-filter">' +
					'<span class="llms-label-text">Show</span>' +
					'<select id="llms-adaptive-filter"></select>' +
				'</label>' +
				'<p class="llms-adaptive-note">A lesson with no stream selected is in every stream.</p>' +
			'</div>'
		);

		renderStreams();
		renderFilter();
	}

	function renderStreams() {
		var $list = $( '#llms-adaptive-stream-list' );

		if ( ! $list.length ) {
			return;
		}

		$list.empty();

		streams.forEach( function( stream ) {
			$list.append(
				'<li data-stream="' + escapeHtml( stream.id ) + '">' +
					'<span>' + escapeHtml( stream.name ) + '</span>' +
					'<button type="button" class="llms-adaptive-remove" aria-label="Remove ' + escapeHtml( stream.name ) + '">&times;</button>' +
				'</li>'
			);
		} );
	}

	function renderFilter() {
		var $select = $( '#llms-adaptive-filter' );

		if ( ! $select.length ) {
			return;
		}

		var html = '<option value="">All lessons</option>';

		streams.forEach( function( stream ) {
			html += '<option value="' + escapeHtml( stream.id ) + '">' + escapeHtml( stream.name ) + '</option>';
		} );

		$select.html( html ).val( filter );
	}

	function paintLessonBadge( $lesson, lessonId ) {
		var tags = lessonTags( lessonId );
		var label = tags.length ? tags.map( streamName ).join( ', ' ) : 'Every stream';
		var $badge = $lesson.children( '.llms-builder-header' ).find( '.llms-adaptive-badge' );

		if ( ! $badge.length ) {
			$badge = $( '<span class="llms-adaptive-badge"></span>' );
			$lesson.children( '.llms-builder-header' ).find( '.llms-action-icons-left' ).prepend( $badge );
		}

		if ( $badge.text() !== label ) {
			$badge.text( label );
		}

		$badge.toggleClass( 'is-every', ! tags.length );
	}

	function applyFilter() {
		if ( applying ) {
			return;
		}

		applying = true;

		$( '#llms-sections .llms-lesson' ).each( function() {
			var id = $( this ).attr( 'data-id' );
			$( this ).toggleClass( 'llms-adaptive-hidden', ! lessonInFilter( id ) );
			paintLessonBadge( $( this ), id );
		} );

		$( '#llms-sections .llms-section' ).each( function() {
			var visible = $( this ).find( '.llms-lesson' ).not( '.llms-adaptive-hidden' ).length;
			$( this ).toggleClass( 'llms-adaptive-hidden', !! filter && ! visible );
		} );

		applying = false;
	}

	function addStream( name ) {
		name = $.trim( name );

		if ( ! name ) {
			return;
		}

		streams.push( {
			id: uniqueId( name ),
			name: name,
		} );

		$( '#llms-adaptive-stream-name' ).val( '' );
		renderStreams();
		renderFilter();
		renderLessonPanel();
		renderQuizPanel();
		applyFilter();
	}

	function removeStream( id ) {
		streams = streams.filter( function( stream ) {
			return stream.id !== id;
		} );

		Object.keys( assignments ).forEach( function( lessonId ) {
			assignments[ lessonId ] = assignments[ lessonId ].filter( function( streamId ) {
				return streamId !== id;
			} );
		} );

		if ( filter === id ) {
			filter = '';
		}

		renderStreams();
		renderFilter();
		renderLessonPanel();
		renderQuizPanel();
		applyFilter();
	}

	function renderLessonPanel() {
		var $tab = $( '#llms-editor-lesson' );

		if ( ! $tab.length || ! $tab.hasClass( 'active' ) || ! activeLesson ) {
			return;
		}

		var lessonId = String( activeLesson.get( 'id' ) );
		var tags = lessonTags( lessonId );
		var $panel = $( '#llms-adaptive-lesson-streams' );

		if ( ! $panel.length ) {
			$tab.prepend( '<section class="llms-model-settings active" id="llms-adaptive-lesson-streams"></section>' );
			$panel = $( '#llms-adaptive-lesson-streams' );
		}

		var boxes = '';

		if ( ! streams.length ) {
			boxes = '<p class="llms-adaptive-empty">Add a stream on the course outline first.</p>';
		} else {
			streams.forEach( function( stream ) {
				var checked = tags.indexOf( stream.id ) !== -1 ? ' checked' : '';
				boxes +=
					'<label class="llms-adaptive-check">' +
						'<input type="checkbox" data-stream="' + escapeHtml( stream.id ) + '"' + checked + '>' +
						'<span>' + escapeHtml( stream.name ) + '</span>' +
					'</label>';
			} );
		}

		$panel.html(
			'<header class="llms-settings-group-header"><h4 class="llms-settings-group-title">Streams</h4></header>' +
			'<div class="llms-settings-group-body">' +
				boxes +
				'<p class="llms-adaptive-note">Leave all of these unchecked to include this lesson in every stream.</p>' +
			'</div>'
		);
	}

	function quizModel() {
		if ( ! activeLesson ) {
			return null;
		}

		var quiz = activeLesson.get( 'quiz' );

		return quiz && quiz.get ? quiz : null;
	}

	function forkState( quizId ) {
		if ( ! quizForks[ quizId ] ) {
			quizForks[ quizId ] = {
				targetType: 'lesson',
				targetId: '',
				removeOnPass: false,
			};
		}

		return quizForks[ quizId ];
	}

	function retakesAllowed( quiz ) {
		if ( ! quiz ) {
			return true;
		}

		if ( 'yes' === quiz.get( 'disable_retake' ) ) {
			return false;
		}

		if ( 'yes' === quiz.get( 'limit_attempts' ) && parseInt( quiz.get( 'allowed_attempts' ), 10 ) <= 1 ) {
			return false;
		}

		return true;
	}

	function renderQuizPanel() {
		var $tab = $( '#llms-editor-quiz' );
		var quiz = quizModel();

		if ( ! $tab.length || ! $tab.hasClass( 'active' ) || ! quiz ) {
			return;
		}

		var quizId = String( quiz.get( 'id' ) || quiz.cid );
		var state = forkState( quizId );
		var allowed = retakesAllowed( quiz );
		var options = '<option value="">Choose one</option>';
		var $panel = $( '#llms-adaptive-quiz-fork' );

		if ( 'section' === state.targetType ) {
			var model = course();
			if ( model && model.get( 'sections' ) ) {
				model.get( 'sections' ).each( function( section ) {
					options += '<option value="' + escapeHtml( section.get( 'id' ) ) + '">' + escapeHtml( section.get( 'title' ) ) + '</option>';
				} );
			}
		} else {
			eachLesson( function( lesson ) {
				var tags = lessonTags( lesson.get( 'id' ) );
				var suffix = tags.length ? ' (' + tags.map( streamName ).join( ', ' ) + ')' : ' (every stream)';
				options += '<option value="' + escapeHtml( lesson.get( 'id' ) ) + '">' + escapeHtml( lesson.get( 'title' ) ) + escapeHtml( suffix ) + '</option>';
			} );
		}

		if ( ! $panel.length ) {
			var $fields = $tab.find( '#llms-quiz-settings-fields' );
			$panel = $( '<section class="llms-model-settings active" id="llms-adaptive-quiz-fork"></section>' );

			if ( $fields.length ) {
				$fields.after( $panel );
			} else {
				$tab.append( $panel );
			}
		}

		$panel.html(
			'<header class="llms-settings-group-header"><h4 class="llms-settings-group-title">If this quiz is failed</h4></header>' +
			'<div class="llms-settings-group-body">' +
				'<div class="llms-settings-row">' +
					'<div class="llms-settings-field">' +
						'<span class="llms-label"><span class="llms-label-text">Reveal</span></span>' +
						'<div class="llms-adaptive-select">' +
							'<select id="llms-adaptive-fork-type">' +
								'<option value="lesson"' + ( state.targetType === 'lesson' ? ' selected' : '' ) + '>A lesson</option>' +
								'<option value="section"' + ( state.targetType === 'section' ? ' selected' : '' ) + '>A section</option>' +
							'</select>' +
						'</div>' +
					'</div>' +
					'<div class="llms-settings-field">' +
						'<span class="llms-label"><span class="llms-label-text">' + ( state.targetType === 'section' ? 'Section' : 'Lesson' ) + '</span></span>' +
						'<div class="llms-adaptive-select">' +
							'<select id="llms-adaptive-fork-target">' + options + '</select>' +
						'</div>' +
					'</div>' +
				'</div>' +
				'<label class="llms-adaptive-check' + ( allowed ? '' : ' is-disabled' ) + '">' +
					'<input type="checkbox" id="llms-adaptive-fork-retake"' + ( state.removeOnPass && allowed ? ' checked' : '' ) + ( allowed ? '' : ' disabled' ) + '>' +
					'<span>If they retake and pass, remove it from the path</span>' +
				'</label>' +
				'<p class="llms-adaptive-note">' +
					( allowed
						? 'The lesson or section stays hidden until they fail. It then blocks the next lesson and course completion.'
						: 'This quiz does not allow another attempt, so the lesson or section stays on the path after they fail.' ) +
				'</p>' +
			'</div>'
		);

		if ( state.targetId ) {
			$panel.find( '#llms-adaptive-fork-target' ).val( state.targetId );
		}
	}

	function bind() {
		$( document ).on( 'click', '#llms-adaptive-stream-add', function( event ) {
			event.preventDefault();
			addStream( $( '#llms-adaptive-stream-name' ).val() );
		} );

		$( document ).on( 'keydown', '#llms-adaptive-stream-name', function( event ) {
			if ( event.key === 'Enter' ) {
				event.preventDefault();
				addStream( $( this ).val() );
			}
		} );

		$( document ).on( 'click', '.llms-adaptive-remove', function( event ) {
			event.preventDefault();
			removeStream( $( this ).closest( 'li' ).attr( 'data-stream' ) );
		} );

		$( document ).on( 'change', '#llms-adaptive-filter', function() {
			filter = $( this ).val();
			applyFilter();
		} );

		$( document ).on( 'change', '#llms-adaptive-lesson-streams input', function() {
			if ( ! activeLesson ) {
				return;
			}

			var lessonId = String( activeLesson.get( 'id' ) );
			var selected = [];

			$( '#llms-adaptive-lesson-streams input:checked' ).each( function() {
				selected.push( $( this ).attr( 'data-stream' ) );
			} );

			assignments[ lessonId ] = selected;
			applyFilter();
		} );

		$( document ).on( 'change', '#llms-adaptive-fork-type', function() {
			var quiz = quizModel();

			if ( ! quiz ) {
				return;
			}

			var state = forkState( String( quiz.get( 'id' ) || quiz.cid ) );
			state.targetType = $( this ).val();
			state.targetId = '';
			renderQuizPanel();
		} );

		$( document ).on( 'change', '#llms-adaptive-fork-target', function() {
			var quiz = quizModel();

			if ( ! quiz ) {
				return;
			}

			forkState( String( quiz.get( 'id' ) || quiz.cid ) ).targetId = $( this ).val();
		} );

		$( document ).on( 'change', '#llms-adaptive-fork-retake', function() {
			var quiz = quizModel();

			if ( ! quiz ) {
				return;
			}

			forkState( String( quiz.get( 'id' ) || quiz.cid ) ).removeOnPass = $( this ).is( ':checked' );
		} );

		if ( window.Backbone && Backbone.pubSub ) {
			Backbone.pubSub.on( 'lesson-selected', function( lesson, view ) {
				activeLesson = lesson;
				window.setTimeout( function() {
					if ( view === 'quiz' ) {
						renderQuizPanel();
					} else if ( view === 'lesson' ) {
						renderLessonPanel();
					}
				}, 0 );
			} );
		}

		var outline = document.getElementById( 'llms-builder-main' );

		if ( outline && window.MutationObserver ) {
			new MutationObserver( function() {
				if ( applying ) {
					return;
				}
				ensureBar();
				applyFilter();
			} ).observe( outline, {
				childList: true,
				subtree: true,
			} );
		}
	}

	function start() {
		if ( started || ! course() ) {
			return;
		}

		started = true;
		ensureBar();
		applyFilter();
		bind();
	}

	$( document ).on( 'llms-builder-init', start );

	$( function() {
		if ( course() ) {
			start();
		}
	} );

}( jQuery ) );
